CREATE TABLE `schoolbox`.`video_queue`( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `file_id` INT UNSIGNED NOT NULL, `type` ENUM('sbfs','storage') NOT NULL, `status` ENUM('pending','processing','completed') NOT NULL, `created` DATETIME NOT NULL, `modified` DATETIME NOT NULL, PRIMARY KEY (`id`) ) CHARSET=utf8 COLLATE=utf8_general_ci;